/**
 * POST /api/dashboards/check: a dashboard in plain words, for sign-off (D59). The words are generated by code from
 * the payload, never by a model: the title, then each tile by number with its question's restatement, the rule
 * the cell's restater follows (`restate_dashboard`). The cell recomputes them on install and refuses a mismatch,
 * so these words only let a person read what they sign; they authorize nothing.
 */
import { restate, type Question } from "./question-tree.ts"

export const DASHBOARD_ROUTES = ["/api/dashboards/check"] as const
export const isDashboardRoute = (pathname: string) => (DASHBOARD_ROUTES as readonly string[]).includes(pathname)

const MAX_DASHBOARD = 256 * 1024
const refuse = (status: number, reason: string, headers: HeadersInit = {}) =>
  Response.json({ error: reason }, { status, headers: { "cache-control": "no-store", ...headers } })

interface DashboardWords { readonly title: string; readonly tiles: readonly { readonly title?: string; readonly question: Question }[] }

const isDashboard = (value: unknown): value is DashboardWords => {
  const d = value as { title?: unknown; tiles?: unknown } | null
  return d !== null && typeof d === "object" && typeof d.title === "string" && Array.isArray(d.tiles)
    && d.tiles.every((tile: { title?: unknown; question?: unknown } | null) => tile !== null && typeof tile === "object" && (tile.title === undefined || typeof tile.title === "string") && tile.question !== null && typeof tile.question === "object")
}

/** The title line, then "<n>. <tile title>: <question in plain words>" per tile, in order; an untitled tile reads "Untitled question". */
export function restateDashboard(dashboard: DashboardWords): string {
  return [dashboard.title.trim(), ...dashboard.tiles.map((tile, index) => `${index + 1}. ${tile.title?.trim() || "Untitled question"}: ${restate(tile.question)}`)].join("\n")
}

const hex = (bytes: ArrayBuffer) => [...new Uint8Array(bytes)].map((byte) => byte.toString(16).padStart(2, "0")).join("")

export async function dashboardsRoute(request: Request): Promise<Response> {
  if (request.method !== "POST") return refuse(405, "Use POST.", { allow: "POST" })
  const text = await request.text()
  if (text.length > MAX_DASHBOARD) return refuse(413, "The dashboard is too long.")
  let body: unknown
  try {
    body = JSON.parse(text)
  } catch {
    return refuse(400, "Expected {dashboard}.")
  }
  const dashboard = (body as { dashboard?: unknown } | null)?.dashboard
  if (!isDashboard(dashboard)) return refuse(400, "Expected {dashboard: {title, tiles: [{title, question}]}}.")
  const words = restateDashboard(dashboard)
  return Response.json({ restatement: { text: words, sha256: hex(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(words))) } }, { headers: { "cache-control": "no-store" } })
}
